      ++second_vertex;
      typename Traits::Construct_segment_2 construct_segment_2 =
            Traits().construct_segment_2_object();
      const_cast<Polygon_2_const_edge_circulator*>(this)->segment =
          construct_segment_2(*first_vertex, *second_vertex);
      return segment;
